package run.ikaros.game; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/v2/games/assets/{assetId}") public class GameAssetIntegrityController{private final GameAssetIntegrityService service;public GameAssetIntegrityController(GameAssetIntegrityService s){service=s;}@PostMapping("/actions/verify-checksum")public Mono<GameAssetView> verify(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID assetId,@Valid@RequestBody VerifyGameAssetChecksumRequest r){return service.verify(o,assetId,r);}@PostMapping("/actions/restore")public Mono<GameAssetView> restore(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID assetId){return service.requestRestore(o,assetId);}}
